async function registerAccount(){
 if(!supabaseClient)return toast('Supabase is not connected.');
 const email=document.getElementById('authEmail').value.trim().toLowerCase(); const password=document.getElementById('authPassword').value; const name=document.getElementById('authName').value.trim();
 const requestedRole=document.getElementById('authRole')?.value==='manager'?'manager':'parent';
 const owner=email===OWNER_EMAIL;
 const role=owner?'owner':(requestedRole==='manager'?'manager_pending':'parent');
 if(!email||!password||password.length<6||!name)return toast('Enter your name, email and a password of at least 6 characters.');
 const {data,error}=await supabaseClient.auth.signUp({email,password});
 if(error)return toast(error.message);
 if(!data.user)return toast('Account created. Check your email to finish registration.');
 const {error:profileError}=await supabaseClient.from('profiles').upsert({id:data.user.id,name,role,email},{onConflict:'id'});
 if(profileError)return toast('Account created, but profile setup failed: '+profileError.message);
 if(data.session?.user){
   state.authUser=data.user;state.authRole=role;state.parentName=name;state.email=email;state.authMode=null;
   state.view=(role==='owner'||role==='manager')?'manager':'sales';saveLocalOnly();await loadUserData();render();toast(owner?'Owner account created':'Account created');
 }else{
   state.authMode=null;render();toast(owner?'Owner account created. Check your email to confirm the account, then log in.':role==='manager_pending'?'Manager account created. The owner must approve it after you confirm your email.':'Account created. Check your email to confirm the account, then log in.');
 }
}
async function loginAccount(){
 if(!supabaseClient)return toast('Supabase is not connected.');
 const email=document.getElementById('authEmail').value.trim().toLowerCase(); const password=document.getElementById('authPassword').value;
 if(!email||!password)return toast('Enter your email and password.');
 const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});
 if(error)return toast(error.message);
 await setAuthenticatedUser(data.user);state.authMode=null;render();
}
async function setAuthenticatedUser(user){
 state.authUser=user; state.email=user.email||'';
 const {data:profile}=await supabaseClient.from('profiles').select('id,name,role,email').eq('id',user.id).maybeSingle();
 const normalizedEmail=String(user.email||'').toLowerCase();
 if(normalizedEmail===OWNER_EMAIL){
   state.authRole='owner';
   state.parentName=profile?.name||'Owner';
   if(!profile){await supabaseClient.from('profiles').upsert({id:user.id,name:'Owner',role:'owner',email:user.email},{onConflict:'id'});}else if(profile.role!=='owner'){await supabaseClient.from('profiles').update({role:'owner',email:user.email}).eq('id',user.id);}
 }else{
   state.authRole=profile?.role||'parent';
   state.parentName=profile?.name||user.email?.split('@')[0]||'Parent';
 }
 state.view=(state.authRole==='manager'||state.authRole==='owner')?'manager':'sales';
 await loadUserData();saveLocalOnly();
}
async function loadUserData(){
 if(!supabaseClient||!state.authUser)return;
 try{
   if(state.authRole==='manager'||state.authRole==='owner'){
     let pq=supabaseClient.from('programs').select('id,name,sport,sessions,price,attendance_payback,schedule,details,spots,venue_id,manager_id,venues(name)').order('created_at');
     if(state.authRole==='manager')pq=pq.eq('manager_id',state.authUser.id);
     const q=await pq;
     if(!q.error){state.programs=(q.data||[]).filter(p=>p.name!=='Saturday Soccer — U10').map((p,i)=>({id:i+1,dbId:p.id,managerId:p.manager_id,name:p.name,sport:p.sport,sessions:p.sessions||8,price:Number(p.price||0),attendancePayback:Number(p.attendance_payback||0),venue:p.venues?.name||'Venue TBD',details:p.details||'',slots:[{id:'db-'+p.id,label:p.schedule||'Schedule to be announced',spots:p.spots??0,capacity:p.spots??0}]}));}
     if(state.programs.length){const mids=[...new Set(state.programs.map(p=>p.managerId).filter(Boolean))];if(mids.length){const mq=await supabaseClient.from('profiles').select('id,name').in('id',mids);if(!mq.error){const names=Object.fromEntries((mq.data||[]).map(x=>[x.id,x.name]));state.programs=state.programs.map(p=>({...p,managerName:names[p.managerId]||'Program manager'}));}}}
     let r=supabaseClient.from('rewards').select('id,name,description,cost,icon,image_url,manager_id').eq('active',true).order('created_at');
     if(state.authRole==='manager')r=r.eq('manager_id',state.authUser.id);
     const rq=await r;
     if(!rq.error)state.rewards=(rq.data||[]).map((x,i)=>({id:i+1,dbId:x.id,name:x.name,description:x.description||'',cost:x.cost,icon:x.icon||'🎁',image:x.image_url||''}));
     if(isOwner()){
       const people=await supabaseClient.from('profiles').select('id,name,email,role,created_at').order('created_at',{ascending:false});
       if(!people.error)state.people=people.data||[];
     }
   }
   if(state.authRole==='parent'||state.authRole==='owner'){
     const {data:links}=await supabaseClient.from('parent_children').select('child_id').eq('parent_id',state.authUser.id);
     const ids=(links||[]).map(x=>x.child_id);
     if(ids.length){const {data:children}=await supabaseClient.from('children').select('id,name,photo_url').in('id',ids); state.children=children||[]; state.childName=state.children[0]?.name||state.childName; const {data:enroll}=await supabaseClient.from('program_children').select('program_id,child_id').in('child_id',ids); state.enrolledPrograms=[...(enroll||[])];}
   }
 }catch(err){console.warn('User data load skipped.',err)}
}
async function changeUserRole(userId,newRole){
 if(!isOwner())return toast('Owner access required.');
 const allowed=['parent','manager_pending','manager']; if(!allowed.includes(newRole))return toast('Invalid role.');
 const target=(state.people||[]).find(p=>p.id===userId); if(!target)return toast('User not found.');
 if(String(target.email||'').toLowerCase()===OWNER_EMAIL)return toast('The owner account cannot be changed here.');
 const {error}=await supabaseClient.from('profiles').update({role:newRole}).eq('id',userId);
 if(error)return toast('Could not update role: '+error.message);
 state.people=state.people.map(p=>p.id===userId?{...p,role:newRole}:p);
 toast(newRole==='manager'?'Manager approved.':newRole==='parent'?'Changed to Parent.':'Set to pending manager.');render();
}
function ownerPeoplePanel(){
 const people=(state.people||[]).filter(p=>String(p.email||'').toLowerCase()!==OWNER_EMAIL);
 return `<div class="card" style="margin-top:18px"><div class="section-title" style="margin-bottom:12px"><div><span class="pill">Owner controls</span><h3>Manager approvals & accounts</h3><p class="muted">Managers register normally. You decide who is approved as a manager.</p></div></div>${people.length?`<table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Change</th></tr></thead><tbody>${people.map(p=>`<tr><td><b>${p.name||'Unnamed'}</b></td><td>${p.email||'—'}</td><td>${p.role==='manager_pending'?'<span class="pill">Pending manager</span>':p.role}</td><td><select class="input" onchange="changeUserRole('${p.id}',this.value)" style="min-width:150px"><option value="${p.role}" selected>${p.role==='manager_pending'?'Pending manager':p.role}</option><option value="parent">Parent</option><option value="manager_pending">Pending manager</option><option value="manager">Manager</option></select></td></tr>`).join('')}</tbody></table>`:'<div class="notice">No other accounts yet. When someone registers as a manager, their application will appear here.</div>'}</div>`;
}
async function logout(){if(supabaseClient)await supabaseClient.auth.signOut();state.authUser=null;state.authRole=null;state.children=[];state.enrolledPrograms=[];state.view='sales';saveLocalOnly();render();toast('Logged out')}
function toggleProgram(id){state.expandedPrograms[id]=!state.expandedPrograms[id];render()}
function enrolledForChild(childId){return (state.enrolledPrograms||[]).filter(x=>String(x.child_id)===String(childId)).map(x=>String(x.program_id));}
function isEnrolled(programId,childId){return enrolledForChild(childId).includes(String(programId))}
async function enrollInProgram(programId){
 if(!state.authUser)return openAuth('login');
 if(state.authRole!=='parent')return toast('Programs are enrolled through a parent account.');
 const child=state.children[0]; if(!child)return toast('Add a child to your parent account first.');
 const pid=state.programs.find(p=>p.id===programId)?.dbId||programId;
 if(isEnrolled(pid,child.id))return toast('This child is already enrolled in the program.');
 if(!supabaseClient)return toast('Supabase is not connected.');
 const {error}=await supabaseClient.from('program_children').insert({program_id:pid,child_id:child.id});
 if(error)return toast('Could not enroll: '+error.message);
 state.enrolledPrograms.push({program_id:pid,child_id:child.id});saveLocalOnly();toast('Program added to your child');render();
}
async function addChild(){
 if(!state.authUser||state.authRole!=='parent')return;
 const name=prompt('Child name'); if(!name)return;
 const {data:child,error}=await supabaseClient.from('children').insert({name}).select('id,name,photo_url').single();
 if(error)return toast('Could not add child: '+error.message);
 const {error:linkError}=await supabaseClient.from('parent_children').insert({parent_id:state.authUser.id,child_id:child.id});
 if(linkError)return toast('Child created but parent link failed: '+linkError.message);
 state.children.push(child);state.childName=child.name;saveLocalOnly();toast('Child added');render();
}
function programSummary(pr,childId){const enrolled=isEnrolled(pr.dbId||pr.id,childId);return `<div class="card" style="margin-bottom:10px"><button class="program-collapse" onclick="toggleProgram('${pr.id}')"><span><b>${pr.name}</b><span class="small muted">${pr.sessions} sessions • ${money(pr.price)} • ${pr.venue} • ${money(programAttendanceTotal(pr))} attendance payback</span><span class="pill" style="margin-top:6px;display:inline-block">Manager: ${pr.managerName||'Program manager'}</span></span><span>${state.expandedPrograms[pr.id]?'−':'+'}</span></button>${state.expandedPrograms[pr.id]?`<div class="program-expanded"><p>${pr.details}</p><div class="statrow"><span>Manager</span><b>${pr.managerName||'Program manager'}</b></div><div class="statrow"><span>Schedule</span><b>${pr.slots?.[0]?.label||pr.schedule||'Schedule TBD'}</b></div><div class="statrow"><span>Enrollment</span><b>${enrolled?'Registered':'Not registered'}</b></div>${childId?`<button class="btn ${enrolled?'light':'green'}" ${enrolled?'disabled':''} onclick="enrollInProgram(${pr.id})">${enrolled?'Registered':'Add to program'}</button>`:''}</div>`:''}</div>`}
function parseScheduleInput(raw){
 const text=String(raw||'').trim(); const low=text.toLowerCase();
 const dayMap={sun:0,sunday:0,sundays:0,mon:1,monday:1,mondays:1,tue:2,tues:2,tuesday:2,tuesdays:2,wed:3,wednesday:3,wednesdays:3,thu:4,thur:4,thurs:4,thursday:4,thursdays:4,fri:5,friday:5,fridays:5,sat:6,saturday:6,saturdays:6};
 let day=null; for(const k of Object.keys(dayMap)){if(new RegExp('\\b'+k+'\\b').test(low)){day=dayMap[k];break;}}
 const range=low.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\s*(?:-|–|—|to)\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
 if(day===null||!range)return null; let [,h1,m1,ap1,h2,m2,ap2]=range; m1=m1||'00';m2=m2||'00'; if(!ap1&&!ap2){const n=Number(h1); if(n>=1&&n<=7){ap1='pm';ap2='pm';} else {ap1='am';ap2='am';}} else {ap1=ap1||ap2;ap2=ap2||ap1;}
 const norm=(h,m,ap)=>{h=Number(h);if(ap){if(ap==='pm'&&h<12)h+=12;if(ap==='am'&&h===12)h=0;}return String(h).padStart(2,'0')+':'+m;};
 return {day,start:norm(h1,m1,ap1),end:norm(h2,m2,ap2),label:text};
}
function nextDateOnWeekday(startDate,weekday){const d=new Date(startDate+'T12:00:00');d.setDate(d.getDate()+((weekday-d.getDay()+7)%7));return d;}
function parseHolidayDates(raw){return new Set(String(raw||'').split(/[\s,;]+/).map(x=>x.trim()).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)));}
function schedulePreview(){const p=parseScheduleInput(document.getElementById('mSchedule')?.value),count=Math.max(1,Math.min(52,Number(document.getElementById('mSessionCount')?.value)||8)),first=document.getElementById('mFirstDate')?.value,holidays=parseHolidayDates(document.getElementById('mHolidays')?.value);if(!p||!first)return '<div class="notice">Enter a schedule such as <b>Tuesday 5–6 PM</b> and choose a first date. Common formats are accepted.</div>';let d=nextDateOnWeekday(first,p.day),dates=[],guard=0;while(dates.length<count&&guard<370){const iso=d.toISOString().slice(0,10);if(!holidays.has(iso))dates.push(iso);d.setDate(d.getDate()+7);guard++;}return `<div class="success"><b>${dates.length} sessions</b> will be created • ${dates[0]} → ${dates[dates.length-1]}${holidays.size?` • ${holidays.size} blackout date${holidays.size===1?'':'s'}`:''}</div>`;}
function refreshSchedulePreview(){const el=document.getElementById('schedulePreview');if(el)el.innerHTML=schedulePreview();}
function programDbId(pr){return pr?.dbId||pr?.id||null;}
function programAttendanceTotal(pr){return Math.max(0,Number(pr?.attendancePayback||0));}
function attendanceRecord(pr){const key=String(programDbId(pr)||'demo');if(!state.attendanceByProgram)state.attendanceByProgram={};const rec=state.attendanceByProgram[key]||{};return {attended:Math.max(0,Number(rec.attended||0)),paybackIssued:!!rec.paybackIssued,payoutDestination:rec.payoutDestination||state.economics||'parent',lastUpdated:rec.lastUpdated||null};}
function attendanceProgress(pr){const rec=attendanceRecord(pr);const total=Math.max(1,Number(pr?.sessions||state.totalSessions||1));return {attended:Math.min(rec.attended,total),total,payback:programAttendanceTotal(pr),qualified:rec.attended>=total,payoutIssued:rec.paybackIssued,destination:rec.payoutDestination};}
function currentTrackedProgram(){return (state.programs||[]).find(p=>p.dbId&&state.enrolledPrograms?.some(x=>String(x.program_id)===String(p.dbId))) || (state.programs||[]).find(p=>p.dbId) || (state.programs||[])[0] || null;}
function applyAttendancePayback(pr){
 const prog=pr||currentTrackedProgram();if(!prog)return false;const key=String(programDbId(prog));const a=attendanceProgress(prog);
 if(a.qualified&&!a.payoutIssued&&a.payback>0){
   if(!state.attendanceByProgram)state.attendanceByProgram={};
   state.attendanceByProgram[key]={attended:a.attended,paybackIssued:true,payoutDestination:state.economics||'parent',lastUpdated:new Date().toISOString()};
   if((state.economics||'parent')==='kid'){
     state.rewardPoints += a.payback;
     state.ledger.push({date:'Today',description:`Attendance payback — ${prog.name}`,amount:a.payback,type:'earned'});
   }
   return true;
 }
 return false;
}
function setProgramAttendance(pr,attended,source='manager'){
 const prog=pr||currentTrackedProgram();if(!prog)return toast('No program is available for attendance.');const total=Math.max(0,Number(prog.sessions||state.totalSessions||0));let n=Math.max(0,Math.min(total,Number(attended)||0));const key=String(programDbId(prog));const existing=attendanceRecord(prog);if(existing.paybackIssued){n=total;}
 state.attendance=n;state.totalSessions=total||state.totalSessions;state.attendanceByProgram[key]={attended:n,paybackIssued:existing.paybackIssued,payoutDestination:existing.payoutDestination||state.economics||'parent',lastUpdated:new Date().toISOString()};
 const paidNow=applyAttendancePayback(prog);saveLocalOnly();render();toast(paidNow?'Attendance updated — attendance payback automatically awarded.':`Attendance updated to ${n}/${total}.`);
}
function kidCheckIn(){
 const prog=currentTrackedProgram();if(!prog)return toast('No program is enrolled.');const today=new Date().toISOString().slice(0,10);if(state.currentCheckinDate===today)return toast('This session is already checked in.');const a=attendanceProgress(prog);if(a.attended>=a.total)return toast('All program sessions are already marked attended.');state.currentCheckinDate=today;setProgramAttendance(prog,a.attended+1,'kid');}
function managerProgramCard(pr){
 const key='mgr-'+pr.id, sessions=(state.sessions||[]).filter(s=>String(s.programId||s.program)===String(pr.dbId||pr.id)), expanded=!!state.expandedPrograms[key], a=attendanceProgress(pr);
 return `<div class="card" style="margin-bottom:10px"><button class="program-collapse" onclick="toggleProgram('${key}')"><span><b>${pr.name}</b><span class="small muted">${pr.sessions} sessions • ${money(pr.price)} • ${pr.venue} • ${money(programAttendanceTotal(pr))} attendance payback</span><span class="pill" style="margin-top:6px;display:inline-block">Manager: ${pr.managerName||state.parentName||'Program manager'}</span></span><span>${expanded?'−':'+'}</span></button>${expanded?`<div class="program-expanded"><p>${pr.details||'No description yet.'}</p><div class="statrow"><span>Schedule</span><b>${pr.slots?.[0]?.label||pr.schedule||'Schedule TBD'}</b></div><div class="statrow"><span>Planned sessions</span><b>${pr.sessions}</b></div><div class="statrow"><span>Generated sessions</span><b>${sessions.length}</b></div><div class="statrow"><span>Attendance payback</span><b>${money(a.payback)} ${a.payback?'total':'(not allocated)'}</b></div><div class="statrow"><span>Attendance status</span><b>${a.attended}/${a.total}${a.payoutIssued?' • Payback awarded':' • Payback pending'}</b></div><div class="statrow"><span>Payout destination</span><b>${a.destination==='kid'?'Kid wallet':'Parent'}</b></div><div class="notice" style="margin:12px 0"><b>Attendance control</b><div class="small muted" style="margin-top:4px">Set the child's attended-session count here when you need to correct attendance manually. Reaching full attendance automatically awards the manager's allocated payback.</div><div class="button-row" style="margin-top:10px"><input class="input" id="attendance-${pr.id}" type="number" min="0" max="${a.total}" value="${a.attended}" style="max-width:130px"><button class="btn green" onclick="setProgramAttendance(${pr.id},document.getElementById('attendance-${pr.id}').value,'manager')">Save attendance</button><button class="btn light" onclick="setProgramAttendance(${pr.id},${a.total},'manager')">Mark all attended</button></div></div><div class="button-row" style="margin-top:10px"><button class="btn light" onclick="awardPoints('Enthusiasm',10)">+10 Enthusiasm</button><button class="btn light" onclick="awardPoints('Teamwork',10)">+10 Teamwork</button><button class="btn light" onclick="downloadProgramICS(${pr.id})">Add to calendar</button><button class="btn blue" onclick="generateSessions(${pr.id})">Generate sessions</button></div><div class="catalog" style="margin-top:14px">${sessions.map(s=>`<div class="session-admin-row"><div><b>${s.name}</b><div class="small muted">${s.date} • ${s.start}–${s.end} • ${s.venue}</div></div><span class="pill">${s.status}</span></div>`).join('')||'<div class="notice">No sessions generated yet.</div>'}</div></div>`:''}</div>`;
}

function rewardManager(){return `<div class="card" style="margin-top:20px"><h3>My Reward Catalog</h3><p class="muted">This catalog belongs to the signed-in manager. Rewards can include a picture, description and points cost.</p><div class="formgrid"><div><div class="label">Reward</div><input class="input" id="rName" placeholder="Sports Drink"></div><div><div class="label">Points cost</div><input class="input" id="rCost" type="number" value="5"></div><div class="full"><div class="label">Description</div><input class="input" id="rDesc" placeholder="Cold drink after practice"></div><div class="full"><div class="label">Picture</div><input class="input" id="rImage" type="file" accept="image/*" onchange="previewRewardImage(event)"></div></div><button class="btn green" style="margin-top:12px" onclick="addReward()">Add reward</button><div class="catalog">${(state.rewards||[]).map(r=>`<div class="catalog-row">${r.image?`<img src="${r.image}"/>`:'<div class="thumb">🎁</div>'}<div><b>${r.name}</b><div class="small muted">${r.description}</div></div><strong>${r.cost} pts</strong></div>`).join('')||'<div class="notice">No rewards in this catalog yet.</div>'}</div></div>`}
function showProgramForm(){const x=document.getElementById('programForm');if(x)x.style.display='block'}
function hideProgramForm(){const x=document.getElementById('programForm');if(x)x.style.display='none'}
async function generateSessions(pid){
 const p=state.programs.find(x=>x.id===pid);if(!p||!supabaseClient)return toast('Program or Supabase connection missing.');const parsed=parseScheduleInput(p.slots?.[0]?.label||p.schedule||'');if(!parsed)return toast('This program needs a readable schedule before sessions can be generated.');
 const existing=(state.sessions||[]).filter(s=>String(s.programId||s.program)===String(p.dbId||p.id)); if(existing.length>=(p.sessions||8))return toast(`This program already has ${existing.length} sessions. No duplicates were created.`); const first=prompt('First session date (YYYY-MM-DD)',new Date().toISOString().slice(0,10));if(!first)return;const embedded=(p.slots?.[0]?.label||'').match(/skips (.*)$/i);const holidayText=embedded?embedded[1]:prompt('Holiday / blackout dates, comma-separated (YYYY-MM-DD). These dates will be skipped.','');const holidays=parseHolidayDates(holidayText),rows=[],existingDates=new Set(existing.map(s=>s.date));let d=nextDateOnWeekday(first,parsed.day),guard=0;
 while(existing.length+rows.length<(p.sessions||8)&&guard<370){const iso=d.toISOString().slice(0,10);if(!holidays.has(iso)&&!existingDates.has(iso))rows.push({name:p.name,sport:p.sport,session_date:iso,start_time:parsed.start,end_time:parsed.end,status:'committed',description:p.details,max_players:p.slots?.[0]?.capacity||12,program_id:p.dbId||null,venue_id:null});d.setDate(d.getDate()+7);guard++;}
 if(existing.length+rows.length<(p.sessions||8))return toast('Could not create the requested number of sessions.');if(!rows.length)return toast('No new sessions were needed.');const {data,error}=await supabaseClient.from('sessions').insert(rows).select();if(error)return toast('Could not generate sessions: '+error.message);
 state.sessions=[...(state.sessions||[]),...(data||[]).map(s=>({id:s.id,dbId:s.id,name:s.name,sport:s.sport,date:s.session_date,start:s.start_time,end:s.end_time,status:s.status,description:s.description,maxPlayers:s.max_players,programId:s.program_id,program:p.name,venue:p.venue}))];saveLocalOnly();toast(`${data.length} sessions created; blackout dates were skipped.`);render();}
function programSummary(pr,childId){const enrolled=isEnrolled(pr.dbId||pr.id,childId);return `<div class="card" style="margin-bottom:10px"><button class="program-collapse" onclick="toggleProgram('${pr.id}')"><span><b>${pr.name}</b><span class="small muted">${pr.sessions} sessions • ${money(pr.price)} • ${pr.venue} • ${money(programAttendanceTotal(pr))} attendance payback</span><span class="pill" style="margin-top:6px;display:inline-block">Manager: ${pr.managerName||'Program manager'}</span></span><span>${state.expandedPrograms[pr.id]?'−':'+'}</span></button>${state.expandedPrograms[pr.id]?`<div class="program-expanded"><p>${pr.details||''}</p><div class="statrow"><span>Manager</span><b>${pr.managerName||'Program manager'}</b></div><div class="statrow"><span>Schedule</span><b>${pr.slots?.[0]?.label||pr.schedule||'Schedule TBD'}</b></div><div class="statrow"><span>Attendance payback</span><b>${money(programAttendanceTotal(pr))} on full attendance</b></div><div class="statrow"><span>Status</span><b>${enrolled?'Registered':'Available'}</b></div>${childId?`<button class="btn ${enrolled?'light':'green'}" ${enrolled?'disabled':''} onclick="enrollInProgram(${pr.id})">${enrolled?'Registered':'Add to program'}</button>`:''}${childId&&enrolled?`<div class="grid compact" style="margin-top:16px"><div class="card"><b>Schedule</b><p class="muted">Upcoming sessions</p></div><div class="card"><b>History</b><p class="muted">Completed sessions</p></div><div class="card"><b>Rewards</b><p>${state.rewardPoints} points</p></div><div class="card"><b>Videos</b><p class="muted">Session recordings</p></div><div class="card"><b>Accomplishments</b><p class="muted">Progress and badges</p></div></div>`:''}</div>`:''}</div>`}

// ---- Canonical Daily Roll UI / behavior ----
function shell(content){return `<header class="topbar"><div class="brand"><div class="brand-mark">⚽</div>The Daily Roll</div><nav class="nav">${state.authUser?['parent','kid',...(state.authRole==='manager'||state.authRole==='owner'?['manager']:[])].map(v=>`<button class="${state.view===v?'active':''}" onclick="setView('${v}')">${v[0].toUpperCase()+v.slice(1)} View</button>`).join(''):''}<button class="${state.view==='sales'?'active':''}" onclick="setView('sales')">Join a Program</button></nav><div style="display:flex;align-items:center;gap:8px">${authButtons()}</div></header><main class="wrap">${simulationBar()}${content}</main><div class="footer">The Daily Roll • Play • Improve • Earn</div>${state.privacyOpen===true?privacyModal():''}${renderModalSpecial()||''}${state.authMode?authModal():''}`}
function render(){let content;if(state.view==='manager'&&(!state.authUser||!(state.authRole==='manager'||state.authRole==='owner')))content=authRequired();else if((state.view==='parent'||state.view==='kid')&&!state.authUser)content=authRequired();else content=state.view==='sales'?sales():state.view==='parent'?parent():state.view==='kid'?kid():manager();document.getElementById('app').innerHTML=shell(content)}
function sales(){const programs=publicPrograms();const selected=state.selectedProgram?programs.find(p=>p.id===state.selectedProgram):null;return `<section class="hero"><div><span class="pill">Kids sports programs</span><h1>Kids play.<br>Kids improve.<br>Kids earn.</h1><p>Choose a program, create your parent account, and add your child when you're ready.</p><button class="btn green" onclick="document.getElementById('programs').scrollIntoView({behavior:'smooth'})">See available programs</button></div><div class="hero-card"><div class="small">THE DAILY ROLL</div><div class="price">Play • Improve • Earn</div><p>Each manager has their own programs and reward catalog. Attendance payback is allocated per program.</p></div></section><div id="programs" class="section-title"><div><h2>Choose your program</h2><span class="muted">Open a program to see its manager, schedule, location and attendance payback.</span></div>${state.authUser&&state.authRole==='parent'?'<button class="btn light" onclick="setView(\'parent\')">My programs</button>':''}</div><div class="grid">${programs.length?programs.map(pr=>programSummary(pr,state.children[0]?.id)).join(''):'<div class="notice">No public programs are currently available.</div>'}</div>${selected&&state.selectedSlot?checkout(selected):''}`}
function parent(){const kids=state.children.length?state.children:[{id:null,name:state.childName}];return `<div class="section-title"><div><span class="pill">Parent portal</span><h2>Welcome, ${state.parentName} 👋</h2><p class="muted">Manage your children and their enrolled programs.</p></div><div class="button-row"><button class="btn light" onclick="addChild()">+ Add child</button><button class="btn light" onclick="setView('sales')">Browse programs</button></div></div>${kids.map(child=>{const enrolledIds=enrolledForChild(child.id);const enrolled=publicPrograms().filter(p=>enrolledIds.includes(String(p.dbId||p.id)));const open=!!state.expandedPrograms['child-'+child.id];return `<div class="card" style="margin-bottom:18px"><button class="program-collapse" onclick="toggleProgram('child-${child.id}')"><span><b>${child.name}</b><span class="small muted">${enrolled.length} program${enrolled.length===1?'':'s'}</span></span><span>${open?'−':'+'}</span></button>${open?`<div class="program-expanded">${enrolled.length?enrolled.map(pr=>programSummary(pr,child.id)).join(''):'<div class="notice">This child is not registered in a program yet.</div>'}<div class="grid compact" style="margin-top:14px"><div class="card"><b>Schedule</b><p class="muted">Upcoming sessions</p></div><div class="card"><b>History</b><p class="muted">Attendance and past sessions</p></div><div class="card"><b>Rewards</b><p>${state.rewardPoints} points</p></div><div class="card"><b>Videos</b><p class="muted">Session recordings</p></div><div class="card"><b>Accomplishments</b><p class="muted">Progress and badges</p></div></div></div>`:''}</div>`}).join('')}`}
function kid(){const enrolled=publicPrograms().filter(p=>state.enrolledPrograms.some(x=>String(x.program_id)===String(p.dbId||p.id)));const pr=currentTrackedProgram();const a=pr?attendanceProgress(pr):{attended:0,total:0,payback:0,qualified:false,payoutIssued:false,destination:state.economics||'parent'};const spentPoints=Math.abs((state.ledger||[]).filter(x=>x.type==='spent').reduce((sum,x)=>sum+x.amount,0));const attendanceAward=a.payback&&a.payoutIssued&&a.destination==='kid'?a.payback:0;const paybackText=a.payback?(a.payoutIssued?(a.destination==='kid'?`+${a.payback} ⭐ added to your wallet`:`${money(a.payback)} paid back to your parent`):`${money(a.payback)} pending until ${a.total}/${a.total} sessions`):'No attendance payback allocated';return `<div class="section-title"><div><span class="pill">Kid view</span><h2>Hey ${state.childName}! 👋</h2><p class="muted">Your programs, attendance and rewards wallet.</p></div></div><div class="card"><button class="program-collapse" onclick="toggleProgram('kid-programs')"><span><b>My programs</b><span class="small muted">${enrolled.length} registered</span></span><span>${state.expandedPrograms['kid-programs']?'−':'+'}</span></button>${state.expandedPrograms['kid-programs']?`<div class="program-expanded">${enrolled.map(pr=>programSummary(pr,state.children[0]?.id)).join('')||'<div class="notice">No programs are registered yet.</div>'}</div>`:''}</div><div class="grid"><div class="card checkin-card"><h3>Today's check-in</h3><div class="big-check">✓</div><b>${state.currentCheckinDate===new Date().toISOString().slice(0,10)?'Checked in today':'Ready to check in'}</b><div class="statrow" style="margin-top:10px"><span>Attendance</span><b>${a.attended}/${a.total}</b></div><button class="btn light" onclick="kidCheckIn()">Check in for this session</button></div><div class="card"><h3>Rewards wallet</h3><div class="money">${state.rewardPoints} ⭐</div><p class="muted">1 point = $1</p><div class="statrow"><span>Attendance payback</span><b>${paybackText}</b></div><div class="small muted" style="margin-top:8px">${a.total?a.attended+'/'+a.total+' sessions attended. ':''}${a.payback?`Complete every session to unlock the ${money(a.payback)} total payback.`:'Your manager has not allocated an attendance payback.'}</div><div class="small muted" style="margin-top:6px">Spent: ${spentPoints} ⭐${attendanceAward?` • ${attendanceAward} points came from attendance`:''}</div><button class="btn green" style="margin-top:12px" onclick="openSpend()">Spend points</button></div><div class="card"><h3>🏆 MVP voting</h3><p class="muted">Vote for the teammate who tried the hardest today.</p>${state.players.filter(x=>x.name!==state.childName).map(x=>`<button class="vote-card ${state.userVote===x.name?'selected':''}" onclick="castVote('${x.name}')"><b>${x.name}</b></button>`).join('')}<button class="btn blue" style="margin-top:12px;width:100%" ${state.userVote?'disabled':''} onclick="submitVote()">Submit vote</button></div></div>`}
function manager(){const programs=(state.programs||[]).filter(p=>p.name!=='Saturday Soccer — U10');return `<div class="section-title"><div><span class="pill">${isOwner()?'Owner / manager':'Manager'}</span><h2>Program Builder</h2><p class="muted">Programs are permanent offerings. Sessions are generated underneath them.</p></div><button class="btn green" onclick="showProgramForm()">+ Add Program</button></div><div id="programForm" class="card" style="display:none;margin-bottom:18px"><h3>New program</h3><div class="formgrid"><div><div class="label">Program name</div><input class="input" id="mName" placeholder="Tuesday Skills — U8/U10"></div><div><div class="label">Sport</div><input class="input" id="mSport" placeholder="Soccer"></div><div><div class="label">Location</div><input class="input" id="mVenue" placeholder="Burlington Indoor Field"></div><div><div class="label">Price</div><input class="input" id="mPrice" type="number" value="500" min="0"></div><div><div class="label">Attendance payback</div><input class="input" id="mAttendancePayback" type="number" value="100" min="0"><div class="small muted" style="margin-top:5px">Total amount the manager allocates back for completing all sessions. Example: $100 on full attendance.</div></div><div><div class="label">Number of sessions</div><input class="input" id="mSessionCount" type="number" value="8" min="1" max="52" oninput="refreshSchedulePreview()"></div><div><div class="label">First session date</div><input class="input" id="mFirstDate" type="date" value="${new Date().toISOString().slice(0,10)}" onchange="refreshSchedulePreview()"></div><div class="full"><div class="label">Schedule</div><input class="input" id="mSchedule" placeholder="Tuesday 5–6 PM" oninput="refreshSchedulePreview()"><div class="small muted" style="margin-top:5px">Forgiving input: “Tuesday 5–6 PM”, “Tuesdays 5:00–6:00 PM”, “Tue 17:00–18:00”, etc.</div></div><div class="full"><div class="label">Holidays / blackout dates</div><input class="input" id="mHolidays" placeholder="2026-10-13, 2026-11-10" oninput="refreshSchedulePreview()"><div class="small muted" style="margin-top:5px">Skipped dates do not count toward the requested session total.</div></div><div class="full"><div class="label">Description</div><textarea class="input" id="mDetails" rows="3" placeholder="Technical skills, movement and game play."></textarea></div><div class="full" id="schedulePreview">${schedulePreview()}</div></div><div class="button-row"><button class="btn green" onclick="addProgram()">Create program</button><button class="btn light" onclick="hideProgramForm()">Cancel</button></div></div>${programs.length?programs.map(managerProgramCard).join(''):'<div class="notice">No programs created yet. Use <b>+ Add Program</b> to start.</div>'}${rewardManager()}${isOwner()?ownerPeoplePanel():''}`}
async function addProgram(){const name=document.getElementById('mName')?.value.trim();if(!name)return toast('Enter a program name.');const scheduleText=document.getElementById('mSchedule')?.value.trim(),parsed=parseScheduleInput(scheduleText);if(!parsed)return toast('Enter a schedule like Tuesday 5–6 PM.');const firstDate=document.getElementById('mFirstDate')?.value,count=Math.max(1,Math.min(52,Number(document.getElementById('mSessionCount')?.value)||8));if(!firstDate)return toast('Choose the first session date.');const planner=state.scheduleDraft||{};const removed=planner.removed||{};const rows=scheduleWeekRows(firstDate,parsed.day,count,removed);const selectedDates=rows.filter(x=>x.selected).map(x=>x.date);const flags=rows.filter(x=>x.flag).map(x=>`${x.date}: ${x.flag}`);const sport=document.getElementById('mSport')?.value.trim()||'Sports',venue=document.getElementById('mVenue')?.value.trim()||'Location TBD',price=Math.max(0,Number(document.getElementById('mPrice')?.value)||0),attendancePayback=Math.max(0,Number(document.getElementById('mAttendancePayback')?.value)||0),details=document.getElementById('mDetails')?.value.trim()||'',rewardModeValue=document.getElementById('mRewardMode')?.value||'none';if(!supabaseClient||!state.authUser||!(state.authRole==='manager'||state.authRole==='owner'))return toast('Approved manager access is required.');const scheduleLabel=`${scheduleText} • ${count} sessions • ${selectedDates.join(', ')}`;const q=await supabaseClient.from('programs').insert({name,sport,sessions:count,price,attendance_payback:attendancePayback,schedule:scheduleLabel,details,spots:12,manager_id:state.authUser.id}).select('id,name,sport,sessions,price,attendance_payback,schedule,details,spots,venue_id,manager_id').single();if(q.error)return toast('Could not create program: '+q.error.message);const d=q.data;state.programs.push({id:Date.now(),dbId:d.id,managerId:d.manager_id||state.authUser.id,name:d.name,sport:d.sport,sessions:d.sessions||count,price:Number(d.price||0),attendancePayback:Number(d.attendance_payback||0),venue,details:d.details||'',firstDate,scheduleWeeks:selectedDates,removedWeeks:removed,flags,slots:[{id:'db-'+d.id,label:scheduleText,spots:d.spots||12,capacity:d.spots||12}],managerName:state.parentName||'Program manager'});state.rewardModeByProgram[String(d.id)]=rewardModeValue;hideProgramForm();state.scheduleDraft={};saveLocalOnly();toast('Program created');render()}
function deleteSession(id){toast('Sessions are not deleted from the normal workflow. Mark the session cancelled instead.')}

// ---- v10 product hardening / testing flow ----

function awardPoints(kind,amount=10){const n=Math.max(1,Number(amount)||10);state.rewardPoints=(Number(state.rewardPoints)||0)+n;state.ledger=state.ledger||[];state.ledger.push({date:simulationDate(),description:`${kind} bonus`,amount:n,type:'earned'});saveLocalOnly();toast(`+${n} points for ${kind}`);render()}
function downloadProgramICS(p){const dates=plannedDatesForProgram(p);const parsed=parseScheduleInput(p.slots?.[0]?.label||p.schedule||'');if(!dates.length||!parsed)return toast('No scheduled sessions available yet.');const esc=x=>String(x||'').replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');const events=dates.map((d,i)=>`BEGIN:VEVENT\r\nUID:${esc((p.dbId||p.id)+'-'+d)}@thedailyroll.ca\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}\r\nDTSTART:${d.replace(/-/g,'')}T${parsed.start.replace(':','')}00\r\nDTEND:${d.replace(/-/g,'')}T${parsed.end.replace(':','')}00\r\nSUMMARY:${esc(p.name)}\r\nLOCATION:${esc(p.venue)}\r\nDESCRIPTION:${esc(`The Daily Roll • ${state.childName||'Child'} • ${p.sport||''}`)}\r\nEND:VEVENT`).join('\r\n');const ics=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//The Daily Roll//Program Calendar//EN\r\nCALSCALE:GREGORIAN\r\n${events}\r\nEND:VCALENDAR`;const blob=new Blob([ics],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${p.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-schedule.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar file downloaded.')}
function rewardCatalogForProgram(p){return rewardMode(p)==='catalog' ? (state.rewards||[]) : []}
state.simulationOffsetDays = Number(state.simulationOffsetDays||0);
state.simulationBaseDate = state.simulationBaseDate || new Date().toISOString().slice(0,10);
state.votesBySession = state.votesBySession || {};
state.userVotesBySession = state.userVotesBySession || {};
state.publishedMVPBySession = state.publishedMVPBySession || {};
state.rewardModeByProgram = state.rewardModeByProgram || {};
state.locationSearch = state.locationSearch || [];
state.scheduleDraft = state.scheduleDraft || {};

function simulationDate(){const d=new Date(state.simulationBaseDate+'T12:00:00');d.setDate(d.getDate()+Math.max(0,state.simulationOffsetDays));return d.toISOString().slice(0,10)}
function fmtDate(iso){return new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric'}).format(new Date(iso+'T12:00:00'))}
function addDays(iso,n){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function isoWeekStart(iso){const d=new Date(iso+'T12:00:00');const day=d.getDay()||7;d.setDate(d.getDate()-day+1);return d.toISOString().slice(0,10)}
function hdsbFlags(year){
 const out={};
 const add=(a,b,reason)=>{let d=new Date(a+'T12:00:00'),e=new Date(b+'T12:00:00');while(d<=e){out[d.toISOString().slice(0,10)]=reason;d.setDate(d.getDate()+1)}};
 if(year===2026||year===2027){add('2026-09-02','2026-09-03','HDSB PA day');add('2026-10-09','2026-10-09','HDSB PA day');add('2026-11-27','2026-11-27','HDSB PA day');add('2026-12-21','2027-01-01','HDSB Winter Break');add('2027-02-05','2027-02-05','HDSB PA day');add('2027-03-15','2027-03-19','HDSB March Break');add('2027-04-19','2027-04-19','HDSB PA day');add('2027-06-04','2027-06-04','HDSB PA day');add('2027-09-07','2027-09-08','HDSB PA day');}
 return out;
}
function ontarioHolidayFlags(year){
 const out={};
 const fixed=(m,d,name)=>{out[`${year}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`]=name};
 fixed(1,1,'New Year’s Day'); fixed(7,1,'Canada Day'); fixed(12,25,'Christmas Day'); fixed(12,26,'Boxing Day');
 const nth=(month,weekday,n,name)=>{let d=new Date(year,month-1,1,12);let delta=(weekday-d.getDay()+7)%7;d.setDate(1+delta+7*(n-1));out[d.toISOString().slice(0,10)]=name};
 nth(2,1,3,'Family Day'); nth(5,1,2,'Victoria Day'); nth(8,1,1,'Civic Holiday'); nth(9,1,1,'Labour Day'); nth(10,1,2,'Thanksgiving');
 // Good Friday / Easter Monday using Gregorian algorithm.
 const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;
 const easter=new Date(year,month-1,day,12); const gf=new Date(easter);gf.setDate(gf.getDate()-2);const em=new Date(easter);em.setDate(em.getDate()+1);out[gf.toISOString().slice(0,10)]='Good Friday';out[em.toISOString().slice(0,10)]='Easter Monday';
 return out;
}
function scheduleWeekRows(startDate,day,count,removed){
 const rows=[]; let d=nextDateOnWeekday(startDate,day); let guard=0; const target=Math.max(1,Number(count)||8); let included=0;
 while(guard<target+18 && rows.length<target+18){const iso=d.toISOString().slice(0,10);const flags={...hdsbFlags(new Date(iso+'T12:00:00').getFullYear()),...ontarioHolidayFlags(new Date(iso+'T12:00:00').getFullYear())};const flag=flags[iso]||null;const off=!!removed[iso];let selected=included<target&&!off;if(selected)included++;rows.push({date:iso,flag,selected});d.setDate(d.getDate()+7);guard++;}
 // If the manager removes an originally selected week, extend selection to preserve session count.
 for(let i=0;i<rows.length&&included<target;i++){if(!rows[i].selected&&!removed[rows[i].date]){rows[i].selected=true;included++;}}
 return rows;
}
function updateSchedulePlanner(){
 const schedule=document.getElementById('mSchedule')?.value||''; const parsed=parseScheduleInput(schedule); const first=document.getElementById('mFirstDate')?.value; const count=Math.max(1,Math.min(52,Number(document.getElementById('mSessionCount')?.value)||8)); if(!parsed||!first){const e=document.getElementById('schedulePlanner');if(e)e.innerHTML='<div class="notice">Enter a schedule and first date to see the weekly planner.</div>';return;}
 const removed=state.scheduleDraft.removed||{}; const rows=scheduleWeekRows(first,parsed.day,count,removed); state.scheduleDraft={firstDate:first,day:parsed.day,start:parsed.start,end:parsed.end,label:parsed.label,count,removed}; const e=document.getElementById('schedulePlanner');if(e)e.innerHTML=`<div class="schedule-planner"><div class="small muted" style="margin-bottom:8px">Weeks are flagged from the HDSB school calendar and Ontario holidays. A flag is a recommendation—not an automatic cancellation. Remove a week to give families a break; the system extends the program so you still get ${count} sessions.</div>${rows.map((r,i)=>`<div class="week-row ${r.selected?'included':'removed'}"><div><b>Week ${i+1}</b><span class="small muted">${fmtDate(r.date)}</span></div><div>${r.flag?`<span class="pill">⚠ ${r.flag}</span>`:'<span class="small muted">Normal week</span>'}</div><div><button class="btn ${r.selected?'light':'green'}" onclick="toggleScheduleWeek('${r.date}')">${r.selected?'Take week off':'Include week'}</button></div></div>`).join('')}</div>`;
}
function toggleScheduleWeek(date){state.scheduleDraft.removed=state.scheduleDraft.removed||{};if(state.scheduleDraft.removed[date])delete state.scheduleDraft.removed[date];else state.scheduleDraft.removed[date]=true;saveLocalOnly();updateSchedulePlanner()}
function plannedDatesForProgram(p){const raw=p?.scheduleWeeks; if(Array.isArray(raw)&&raw.length)return raw; const parsed=parseScheduleInput(p?.slots?.[0]?.label||p?.schedule||'');if(!parsed)return[];return scheduleWeekRows(p.firstDate||new Date().toISOString().slice(0,10),parsed.day,p.sessions||8,p.removedWeeks||{}).filter(x=>x.selected).map(x=>x.date)}
function currentSessionForProgram(p){const sim=simulationDate();const list=(state.sessions||[]).filter(s=>String(s.programId||s.program)===String(p?.dbId||p?.id));let found=list.find(s=>s.date===sim&&s.status!=='cancelled');if(found)return found;const dates=plannedDatesForProgram(p);const ix=dates.indexOf(sim);if(ix>=0)return {id:`local-${p.id}-${sim}`,dbId:`local-${p.id}-${sim}`,programId:p.dbId||p.id,date:sim,start:p.slots?.[0]?.start||'',end:p.slots?.[0]?.end||'',name:p.name,status:'committed',venue:p.venue};return null}
function currentSessionKey(p){const s=currentSessionForProgram(p);return s?String(s.id||s.dbId):null}
function simulationBar(){if(!state.authUser)return '';const base=state.simulationBaseDate;return `<div class="card simulation-bar"><div><b>Demo clock</b><span class="small muted">${fmtDate(simulationDate())} • ${state.simulationOffsetDays} day${state.simulationOffsetDays===1?'':'s'} from ${fmtDate(base)}</span></div><input aria-label="Simulate days" type="range" min="0" max="120" value="${state.simulationOffsetDays}" oninput="setSimulationDays(this.value)"><div class="button-row"><button class="btn light" onclick="setSimulationDays(0)">Reset</button><button class="btn light" onclick="setSimulationDays(${Math.min(120,state.simulationOffsetDays+7)})">+7 days</button></div></div>`}
function setSimulationDays(n){state.simulationOffsetDays=Math.max(0,Math.min(120,Number(n)||0));state.currentCheckinDate=null;state.userVote=null;saveLocalOnly();render()}
function paymentPreferenceLabel(){return state.paymentMethod==='stripe'?'Credit card':'Cash / EMT'}

function isParentLike(){return state.authRole==='parent'||state.authRole==='owner'}
async function loadUserData(){
 if(!supabaseClient||!state.authUser)return;
 try{
   if(state.authRole==='manager'||state.authRole==='owner'){
     let pq=supabaseClient.from('programs').select('id,name,sport,sessions,price,attendance_payback,schedule,details,spots,venue_id,manager_id,venues(name)').order('created_at'); if(state.authRole==='manager')pq=pq.eq('manager_id',state.authUser.id); const q=await pq;
     if(!q.error)state.programs=(q.data||[]).filter(p=>p.name!=='Saturday Soccer — U10').map((p,i)=>({id:i+1,dbId:p.id,managerId:p.manager_id,name:p.name,sport:p.sport,sessions:p.sessions||8,price:Number(p.price||0),attendancePayback:Number(p.attendance_payback||0),venue:p.venues?.name||'Venue TBD',details:p.details||'',slots:[{id:'db-'+p.id,label:p.schedule||'Schedule to be announced',spots:p.spots??0,capacity:p.spots??0}],managerName:state.parentName||'Program manager'}));
     if(state.programs.length){const mids=[...new Set(state.programs.map(p=>p.managerId).filter(Boolean))];if(mids.length){const mq=await supabaseClient.from('profiles').select('id,name').in('id',mids);if(!mq.error){const names=Object.fromEntries((mq.data||[]).map(x=>[x.id,x.name]));state.programs=state.programs.map(p=>({...p,managerName:names[p.managerId]||'Program manager'}));}}}
     let r=supabaseClient.from('rewards').select('id,name,description,cost,icon,image_url,manager_id').eq('active',true).order('created_at');if(state.authRole==='manager')r=r.eq('manager_id',state.authUser.id);if(state.authRole==='owner')r=r.eq('manager_id',state.authUser.id);const rq=await r;if(!rq.error)state.rewards=(rq.data||[]).map((x,i)=>({id:i+1,dbId:x.id,name:x.name,description:x.description||'',cost:x.cost,icon:x.icon||'🎁',image:x.image_url||''}));
     if(isOwner()){const people=await supabaseClient.from('profiles').select('id,name,email,role,created_at').order('created_at',{ascending:false});if(!people.error)state.people=people.data||[];}
   }
   if(isParentLike()){
     const {data:links}=await supabaseClient.from('parent_children').select('child_id').eq('parent_id',state.authUser.id);const ids=(links||[]).map(x=>x.child_id);
     if(ids.length){const {data:children}=await supabaseClient.from('children').select('id,name,photo_url').in('id',ids);state.children=children||[];state.childName=state.children[0]?.name||state.childName;const {data:enroll}=await supabaseClient.from('program_children').select('program_id,child_id').in('child_id',ids);state.enrolledPrograms=[...(enroll||[])];}
   }
 }catch(err){console.warn('User data load skipped.',err)}
}
function authRequired(){const pending=state.authRole==='manager_pending';return `<div class="card" style="max-width:620px;margin:50px auto;text-align:center"><span class="pill">${pending?'Manager approval pending':'Account required'}</span><h2>${pending?'Your manager account is awaiting approval':'Log in to The Daily Roll'}</h2><p class="muted">${pending?'You registered as a manager. The owner needs to approve your account before Manager View is available.':'Parents can manage children and programs. Owners can also manage a child for testing.'}</p><div class="button-row" style="justify-content:center"><button class="btn blue" onclick="${pending?'logout()':'openAuth(\'login\')'}">${pending?'Log out':'Log in'}</button>${pending?'':'<button class="btn green" onclick="openAuth(\'register\')">Create account</button>'}</div></div>`}
function shell(content){return `<header class="topbar"><div class="brand"><div class="brand-mark">⚽</div>The Daily Roll</div><nav class="nav">${state.authUser?['parent','kid',...(state.authRole==='manager'||state.authRole==='owner'?['manager']:[])].map(v=>`<button class="${state.view===v?'active':''}" onclick="setView('${v}')">${v[0].toUpperCase()+v.slice(1)} View</button>`).join(''):''}<button class="${state.view==='sales'?'active':''}" onclick="setView('sales')">Join a Program</button></nav><div style="display:flex;align-items:center;gap:8px">${authButtons()}</div></header><main class="wrap">${simulationBar()}${content}</main><div class="footer">The Daily Roll • Play • Improve • Earn</div>${state.privacyOpen===true?privacyModal():''}${renderModalSpecial()||''}${state.authMode?authModal():''}`}
function programSummary(pr,childId){const enrolled=isEnrolled(pr.dbId||pr.id,childId);const canJoin=isParentLike()&&childId;return `<div class="card" style="margin-bottom:10px"><button class="program-collapse" onclick="toggleProgram('${pr.id}')"><span><b>${pr.name}</b><span class="small muted">${pr.sessions} sessions • ${money(pr.price)} • ${pr.venue}</span><span class="pill" style="margin-top:6px;display:inline-block">Manager: ${pr.managerName||'Program manager'}</span></span><span>${state.expandedPrograms[pr.id]?'−':'+'}</span></button>${state.expandedPrograms[pr.id]?`<div class="program-expanded"><p>${pr.details||''}</p><div class="statrow"><span>Manager</span><b>${pr.managerName||'Program manager'}</b></div><div class="statrow"><span>Schedule</span><b>${pr.slots?.[0]?.label||pr.schedule||'Schedule TBD'}</b></div><div class="statrow"><span>Attendance payback</span><b>${money(programAttendanceTotal(pr))} on full attendance</b></div><div class="statrow"><span>Rewards</span><b>${rewardMode(pr)==='catalog'?'Manager reward catalog enabled':'No catalog rewards by default'}</b></div><div class="statrow"><span>Status</span><b>${enrolled?'Registered':'Available'}</b></div>${childId&&canJoin?`<button class="btn ${enrolled?'light':'green'}" ${enrolled?'disabled':''} onclick="enrollInProgram(${pr.id})">${enrolled?'Registered':'Join this program'}</button>`:!state.authUser?'<button class="btn green" onclick="openAuth(\'register\')">Register to join</button>':!childId?'<div class="notice">Add a child in Parent View before joining this program.</div>':''}${childId&&enrolled?`<div class="grid compact" style="margin-top:16px"><div class="card"><b>Schedule</b><p class="muted">Upcoming sessions</p></div><div class="card"><b>History</b><p class="muted">Completed sessions</p></div><div class="card"><b>Rewards</b><p>${state.rewardPoints} points</p></div><div class="card"><b>Videos</b><p class="muted">Session recordings</p></div><div class="card"><b>Accomplishments</b><p class="muted">Progress and badges</p></div></div>`:''}</div>`:''}</div>`}
function rewardMode(pr){return state.rewardModeByProgram[String(programDbId(pr))]||'none'}
function setRewardMode(pid,mode){state.rewardModeByProgram[String(pid)]=mode;saveLocalOnly();render()}
function checkout(p){const sl=p.slots?.[0]||{label:p.schedule||'Schedule TBD'};return `<div class="section-title"><div><h2>Join ${p.name}</h2><span class="muted">Add your child, confirm the program, then choose how you want to pay.</span></div></div><div class="checkout-layout"><div class="card"><h3>Enrollment</h3><div class="formgrid"><div><div class="label">Parent name</div><input class="input" id="parent" value="${state.parentName}"></div><div><div class="label">Child name</div><input class="input" id="child" value="${state.childName}"></div><div><div class="label">Email</div><input class="input" id="email" type="email" value="${state.email}"></div><div><div class="label">Phone</div><input class="input" id="phone" type="tel" value="${state.phone}"></div></div><div class="notice" style="margin-top:18px">Child photo can be added later. It is not required to join.</div></div><div class="card sticky-summary"><h3>Payment summary</h3><div class="statrow"><span>Program</span><b>${money(p.price)}</b></div><div class="statrow"><span>Attendance payback</span><b>${money(p.attendancePayback||0)}</b></div><div class="statrow"><span>Reward catalog</span><b>${rewardMode(p)==='catalog'?'Manager catalog enabled':'No rewards by default'}</b></div><div class="divider"></div><div class="statrow total"><span>Total</span><b>${money(p.price)}</b></div><div style="margin-top:14px"><div class="label">Attendance payback goes to</div><select class="input" id="paybackDestination"><option value="parent">Parent</option><option value="kid">Kid wallet</option></select></div><div style="margin-top:14px"><div class="label">Payment method</div><select class="input" id="paymentMethod"><option value="cash">Cash</option><option value="emt">EMT</option>${PAYMENT_VARIANT==='stripe'?'<option value="stripe">Credit card</option>':''}</select></div><button class="btn green" style="width:100%;margin-top:14px" onclick="openPrivacy()">Continue</button><p class="small muted">You will acknowledge the privacy/video terms before payment.</p></div></div>`}
function continueToPayment(){if(!state.consent)return;state.privacyOpen=false;state.paymentMethod=document.getElementById('paymentMethod')?.value||PAYMENT_DEFAULT;state.economics=document.getElementById('paybackDestination')?.value||'parent';saveLocalOnly();render();setTimeout(()=>processSelectedPayment(),50)}
async function processSelectedPayment(){const p=(state.programs||[]).find(x=>x.id===state.selectedProgram)||currentTrackedProgram();if(!p)return toast('Choose a program first.');if(state.paymentMethod==='stripe'){return startStripeCheckout(p)}completePurchase(state.paymentMethod);}
async function completePurchase(method='cash'){const p=(state.programs||[]).find(x=>x.id===state.selectedProgram)||currentTrackedProgram();if(!p)return toast('Choose a program first.');state.paid=true;state.paymentMethod=method;const child=state.children?.[0];if(child&&!isEnrolled(p.dbId||p.id,child.id)&&supabaseClient){const q=await supabaseClient.from('program_children').insert({program_id:p.dbId||p.id,child_id:child.id});if(q.error&&q.error.code!=='23505')return toast('Payment recorded, but enrollment failed: '+q.error.message);state.enrolledPrograms.push({program_id:p.dbId||p.id,child_id:child.id});}else if(child&&!isEnrolled(p.dbId||p.id,child.id)){state.enrolledPrograms.push({program_id:p.dbId||p.id,child_id:child.id});}const key=String(programDbId(p));state.attendanceByProgram[key]={attended:0,paybackIssued:false,payoutDestination:state.economics||'parent'};state.scheduleWeeks=plannedDatesForProgram(p);saveLocalOnly();toast(method==='emt'?'Enrollment recorded — EMT payment selected.':method==='cash'?'Enrollment recorded — cash payment selected.':'Payment successful.');state.selectedProgram=null;state.selectedSlot=null;setView('parent')}
function sales(){const programs=publicPrograms();return `<section class="hero"><div><span class="pill">Kids sports programs</span><h1>Kids play.<br>Kids improve.<br>Kids earn.</h1><p>Choose a program, see the manager, add your child and join.</p><button class="btn green" onclick="document.getElementById('programs').scrollIntoView({behavior:'smooth'})">See available programs</button></div><div class="hero-card"><div class="small">THE DAILY ROLL</div><div class="price">Play • Improve • Earn</div><p>Every program shows its manager. Each manager controls their own reward catalog.</p></div></section><div id="programs" class="section-title"><div><h2>Choose your program</h2><span class="muted">Programs are grouped by manager so parents know exactly who runs them.</span></div>${isParentLike()?'<button class="btn light" onclick="setView(\'parent\')">My children</button>':'<button class="btn light" onclick="openAuth(\'register\')">Register as parent</button>'}</div><div class="grid">${programs.length?programs.map(pr=>programSummary(pr,state.children[0]?.id)).join(''):'<div class="notice">No public programs are currently available.</div>'}</div>${state.selectedProgram?checkout(programs.find(p=>p.id===state.selectedProgram)||programs[0]):''}`}
async function enrollInProgram(programId){if(!state.authUser)return openAuth('register');if(!isParentLike())return toast('Manager accounts cannot enroll children. Owner accounts can test parent enrollment.');let child=state.children?.[0];if(!child){await addChild();child=state.children?.[0];}if(!child)return toast('Add a child before joining.');const p=state.programs.find(x=>x.id===programId);if(!p)return toast('Program not found.');state.selectedProgram=programId;state.selectedSlot=p.slots?.[0]?.id||null;state.parentName=state.parentName||'Parent';state.childName=child.name;state.view='sales';saveLocalOnly();render()}
async function addChild(){if(!state.authUser||!isParentLike())return toast('Log in as a parent or owner to add a child.');const name=prompt('Child name');if(!name)return; if(!supabaseClient)return toast('Supabase is not connected.');const {data:child,error}=await supabaseClient.from('children').insert({name:name.trim()}).select('id,name,photo_url').single();if(error)return toast('Could not add child: '+error.message);const {error:linkError}=await supabaseClient.from('parent_children').insert({parent_id:state.authUser.id,child_id:child.id});if(linkError)return toast('Child created but could not link it to this account: '+linkError.message);state.children.push(child);state.childName=child.name;saveLocalOnly();toast('Child added');render()}
function parent(){const kids=state.children;return `<div class="section-title"><div><span class="pill">Parent portal${state.authRole==='owner'?' • Owner testing':' '}</span><h2>Welcome, ${state.parentName} 👋</h2><p class="muted">Manage children and enrolled programs.</p></div><div class="button-row"><button class="btn light" onclick="addChild()">+ Add child</button><button class="btn light" onclick="setView('sales')">Join a program</button></div></div>${kids.length?kids.map(child=>{const enrolledIds=enrolledForChild(child.id);const enrolled=publicPrograms().filter(p=>enrolledIds.includes(String(p.dbId||p.id)));const open=!!state.expandedPrograms['child-'+child.id];return `<div class="card" style="margin-bottom:18px"><button class="program-collapse" onclick="toggleProgram('child-${child.id}')"><span><b>${child.name}</b><span class="small muted">${enrolled.length} program${enrolled.length===1?'':'s'}</span></span><span>${open?'−':'+'}</span></button>${open?`<div class="program-expanded">${enrolled.length?enrolled.map(pr=>programSummary(pr,child.id)).join(''):'<div class="notice">No programs yet. Click Join a program.</div>'}<div class="grid compact" style="margin-top:14px"><div class="card"><b>Schedule</b><p class="muted">${fmtDate(simulationDate())} • upcoming sessions</p>${enrolled.map(x=>`<button class="btn light" style="margin-top:8px" onclick="downloadProgramICS(${x.id})">Add ${x.name} to calendar</button>`).join('')}</div><div class="card"><b>History</b><p class="muted">Attendance and past sessions</p></div><div class="card"><b>Rewards</b><p>${state.rewardPoints} points</p></div><div class="card"><b>Videos</b><p class="muted">Session recordings</p></div><div class="card"><b>Accomplishments</b><p class="muted">Progress and badges</p></div></div></div>`:''}</div>`}).join(''):'<div class="card"><div class="notice">No children yet. Click <b>+ Add child</b> to get started.</div></div>'}`}
function sessionVoteData(p){const key=currentSessionKey(p)||`preview-${p?.id}`;state.votesBySession[key]=state.votesBySession[key]||{};return {key,votes:state.votesBySession[key]}}
function castVote(name){const p=currentTrackedProgram();if(!p)return toast('No enrolled program.');const s=currentSessionForProgram(p);if(!s)return toast('Voting opens on a session day. Use the Demo clock to move to a session.');const {key,votes}=sessionVoteData(p);if(state.userVotesBySession[key])return toast('You already voted for this session.');state.currentVote=name;render()}
function submitVote(){const p=currentTrackedProgram();if(!p||!state.currentVote)return toast('Pick a teammate first.');const s=currentSessionForProgram(p);if(!s)return toast('Voting opens on a session day.');const {key,votes}=sessionVoteData(p);if(state.userVotesBySession[key])return toast('You already voted for this session.');votes[state.currentVote]=(votes[state.currentVote]||0)+1;state.userVotesBySession[key]=state.currentVote;state.currentVote=null;saveLocalOnly();toast('Vote recorded for this session');render()}
function mvpTable(p){const prog=p||currentTrackedProgram();const s=prog&&currentSessionForProgram(prog);if(!s)return `<div class="notice">No session on ${fmtDate(simulationDate())}. Move the Demo clock to a session day to see voting.</div>`;const {key,votes}=sessionVoteData(prog);const names=(state.players||[]).map(x=>x.name).filter(n=>n!==state.childName);const rows=names.map(n=>[n,votes[n]||0]).sort((a,b)=>b[1]-a[1]);return `<div class="card"><h3>🏆 MVP voting • ${fmtDate(s.date)}</h3><table class="table"><thead><tr><th>Player</th><th>Votes</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td>${v}</td></tr>`).join('')}</tbody></table><div style="margin-top:12px"><select class="input" id="mvpSelect-${prog.id}"><option value="">Use vote leader</option>${names.map(n=>`<option value="${n}" ${state.publishedMVPBySession[key]===n?'selected':''}>${n}</option>`).join('')}</select><button class="btn green" style="margin-top:10px" onclick="publishMVP(${prog.id})">Publish MVP</button></div>${state.publishedMVPBySession[key]?`<div class="success" style="margin-top:12px">Published MVP: <b>${state.publishedMVPBySession[key]}</b></div>`:''}</div>`}
function publishMVP(pid){const p=(state.programs||[]).find(x=>x.id===pid)||currentTrackedProgram();const s=p&&currentSessionForProgram(p);if(!s)return toast('No session selected.');const {key,votes}=sessionVoteData(p);const chosen=document.getElementById(`mvpSelect-${p.id}`)?.value;const leader=Object.entries(votes).sort((a,b)=>b[1]-a[1])[0];state.publishedMVPBySession[key]=chosen||(leader&&leader[1]>0?leader[0]:null);saveLocalOnly();toast('MVP published for this session');render()}
function kidCheckIn(){const p=currentTrackedProgram();if(!p)return toast('No enrolled program.');const s=currentSessionForProgram(p);if(!s)return toast('No session today. Move the Demo clock to a session date.');const key=String(programDbId(p));const rec=attendanceRecord(p);const attendedDates=state.attendedSessionDates||{};attendedDates[key]=attendedDates[key]||{};if(attendedDates[key][s.date])return toast('Already checked in for this session.');attendedDates[key][s.date]=true;state.attendedSessionDates=attendedDates;setProgramAttendance(p,Math.min((rec.attended||0)+1,p.sessions||8),'kid')}
function kid(){const enrolled=publicPrograms().filter(p=>state.enrolledPrograms.some(x=>String(x.program_id)===String(p.dbId||p.id)));const pr=currentTrackedProgram();const a=pr?attendanceProgress(pr):{attended:0,total:0,payback:0,qualified:false,payoutIssued:false,destination:state.economics||'parent'};const session=pr&&currentSessionForProgram(pr);const key=session&&String(session.id||session.dbId);const voted=key&&state.userVotesBySession[key];const spentPoints=Math.abs((state.ledger||[]).filter(x=>x.type==='spent').reduce((sum,x)=>sum+x.amount,0));const attendanceAward=a.payback&&a.payoutIssued&&a.destination==='kid'?a.payback:0;return `<div class="section-title"><div><span class="pill">Kid view</span><h2>Hey ${state.childName}! 👋</h2><p class="muted">${fmtDate(simulationDate())} • Your programs, attendance, teamwork and enthusiasm.</p></div></div><div class="card"><button class="program-collapse" onclick="toggleProgram('kid-programs')"><span><b>My programs</b><span class="small muted">${enrolled.length} registered</span></span><span>${state.expandedPrograms['kid-programs']?'−':'+'}</span></button>${state.expandedPrograms['kid-programs']?`<div class="program-expanded">${enrolled.map(pr=>programSummary(pr,state.children[0]?.id)).join('')||'<div class="notice">No programs are registered yet.</div>'}</div>`:''}</div><div class="grid"><div class="card checkin-card"><h3>Session</h3><div class="big-check">✓</div><b>${session?'Session day':'No session today'}</b><div class="statrow" style="margin-top:10px"><span>Attendance</span><b>${a.attended}/${a.total}</b></div><button class="btn light" onclick="kidCheckIn()">${session?'Check in for this session':'Check in unavailable'}</button></div><div class="card"><h3>Rewards wallet</h3><div class="money">${state.rewardPoints} ⭐</div><p class="muted">1 point = $1</p><div class="statrow"><span>Attendance payback</span><b>${a.payback?(a.payoutIssued?(a.destination==='kid'?`+${a.payback} ⭐`:`${money(a.payback)} to parent`):`${money(a.payback)} pending`):'None allocated'}</b></div><div class="small muted" style="margin-top:8px">Kids can earn points for <b>enthusiasm</b> and <b>teamwork</b> even when the program has no reward catalog.</div>${rewardMode(pr)==='catalog'?`<button class="btn green" style="margin-top:12px" onclick="openSpend()">Spend catalog points</button>`:'<div class="notice" style="margin-top:12px">No reward catalog is enabled for this program.</div>'}</div><div class="card"><h3>🏆 MVP voting</h3><p class="muted">${session?'Vote for the teammate who tried the hardest today.':'Voting opens on session days.'}</p>${session?state.players.filter(x=>x.name!==state.childName).map(x=>`<button class="vote-card ${state.currentVote===x.name?'selected':''} ${voted===x.name?'selected':''}" ${voted?'disabled':''} onclick="castVote('${x.name}')"><b>${x.name}</b></button>`).join(''):''}<button class="btn blue" style="margin-top:12px;width:100%" ${(!state.currentVote||voted||!session)?'disabled':''} onclick="submitVote()">${voted?'Vote submitted':'Submit vote'}</button></div></div>`}
function manager(){const programs=(state.programs||[]).filter(p=>p.name!=='Saturday Soccer — U10');return `<div class="section-title"><div><span class="pill">${isOwner()?'Owner / manager':'Manager'}</span><h2>Program Builder</h2><p class="muted">Programs stay permanent. Weekly planning determines the sessions underneath them.</p></div><button class="btn green" onclick="showProgramForm()">+ Add Program</button></div><div id="programForm" class="card" style="display:none;margin-bottom:18px"><h3>New program</h3><div class="formgrid"><div><div class="label">Program name</div><input class="input" id="mName" placeholder="Tuesday Skills — U8/U10"></div><div><div class="label">Sport</div><input class="input" id="mSport" placeholder="Soccer"></div><div><div class="label">Location</div><div style="display:flex;gap:8px"><input class="input" id="mVenue" placeholder="Search a real venue"><button class="btn light" type="button" onclick="searchRealLocation()">Search</button></div><div id="locationResults" class="catalog" style="margin-top:8px"></div></div><div><div class="label">Price</div><input class="input" id="mPrice" type="number" value="500" min="0"></div><div><div class="label">Attendance payback</div><input class="input" id="mAttendancePayback" type="number" value="100" min="0"><div class="small muted">Total payback for completing every session. Example: $100 total on an $500 program.</div></div><div><div class="label">Number of sessions</div><input class="input" id="mSessionCount" type="number" value="8" min="1" max="52" oninput="updateSchedulePlanner()"></div><div><div class="label">First session date</div><input class="input" id="mFirstDate" type="date" value="${new Date().toISOString().slice(0,10)}" onchange="updateSchedulePlanner()"></div><div class="full"><div class="label">Schedule</div><input class="input" id="mSchedule" placeholder="Tuesday 5–6 PM" oninput="updateSchedulePlanner()"><div class="small muted">Forgiving input: Tuesday 5–6 PM, Tuesdays 5:00–6:00 PM, Tue 17:00–18:00.</div></div><div class="full"><div id="schedulePlanner" class="schedule-planner"><div class="notice">Enter a schedule and first date to see the weekly planner.</div></div></div><div class="full"><div class="label">Details</div><textarea class="input" id="mDetails" rows="3" placeholder="Technical skills, movement and game play."></textarea></div><div class="full"><div class="label">Rewards</div><select class="input" id="mRewardMode"><option value="none">No rewards (default)</option><option value="catalog">Enable manager reward catalog</option></select><div class="small muted">Even with no catalog, kids can still earn points for enthusiasm and teamwork.</div></div></div><div class="button-row"><button class="btn green" onclick="addProgram()">Create program</button><button class="btn light" onclick="hideProgramForm()">Cancel</button></div></div>${programs.length?programs.map(p=>managerProgramCard(p)).join(''):'<div class="notice">No programs created yet.</div>'}${programs.length?programs.map(p=>mvpTable(p)).join(''):''}${rewardManager()}${isOwner()?ownerPeoplePanel():''}`}
function managerProgramCard(pr){const key='mgr-'+pr.id,sessions=(state.sessions||[]).filter(s=>String(s.programId||s.program)===String(pr.dbId||pr.id)),expanded=!!state.expandedPrograms[key],a=attendanceProgress(pr);return `<div class="card" style="margin-bottom:10px"><button class="program-collapse" onclick="toggleProgram('${key}')"><span><b>${pr.name}</b><span class="small muted">${pr.sessions} sessions • ${money(pr.price)} • ${pr.venue} • ${money(programAttendanceTotal(pr))} payback</span><span class="pill" style="margin-top:6px;display:inline-block">Manager: ${pr.managerName||'Program manager'}</span></span><span>${expanded?'−':'+'}</span></button>${expanded?`<div class="program-expanded"><p>${pr.details||'No description yet.'}</p><div class="statrow"><span>Schedule</span><b>${pr.slots?.[0]?.label||pr.schedule||'Schedule TBD'}</b></div><div class="statrow"><span>Planned sessions</span><b>${pr.sessions}</b></div><div class="statrow"><span>Generated sessions</span><b>${sessions.length}</b></div><div class="statrow"><span>Reward mode</span><b>${rewardMode(pr)==='catalog'?'Manager catalog':'No rewards by default'}</b></div><div class="statrow"><span>Attendance</span><b>${a.attended}/${a.total}${a.payoutIssued?' • payback awarded':' • payback pending'}</b></div><div class="notice" style="margin:12px 0"><b>Attendance control</b><div class="button-row" style="margin-top:10px"><input class="input" id="attendance-${pr.id}" type="number" min="0" max="${a.total}" value="${a.attended}" style="max-width:130px"><button class="btn green" onclick="setProgramAttendance(${pr.id},document.getElementById('attendance-${pr.id}').value,'manager')">Save attendance</button><button class="btn light" onclick="setProgramAttendance(${pr.id},${a.total},'manager')">Mark all attended</button></div></div><div class="button-row" style="margin-top:10px"><button class="btn light" onclick="awardPoints('Enthusiasm',10)">+10 Enthusiasm</button><button class="btn light" onclick="awardPoints('Teamwork',10)">+10 Teamwork</button><button class="btn light" onclick="downloadProgramICS(${pr.id})">Add to calendar</button><button class="btn blue" onclick="generateSessions(${pr.id})">Generate sessions</button></div><div class="catalog" style="margin-top:14px">${sessions.map(s=>`<div class="session-admin-row"><div><b>${s.name}</b><div class="small muted">${s.date} • ${s.start}–${s.end} • ${s.venue}</div></div><span class="pill">${s.status}</span></div>`).join('')||'<div class="notice">No sessions generated yet.</div>'}</div></div>`:''}</div>`}
function rewardManager(){return `<div class="card" style="margin-top:20px"><h3>My Reward Catalog</h3><p class="muted">Catalog rewards are OFF by default per program. Kids can still earn enthusiasm and teamwork points.</p><div class="formgrid"><div><div class="label">Reward</div><input class="input" id="rName" placeholder="Sports Drink"></div><div><div class="label">Points cost</div><input class="input" id="rCost" type="number" value="5"></div><div class="full"><div class="label">Description</div><input class="input" id="rDesc" placeholder="Cold drink after practice"></div></div><button class="btn green" style="margin-top:12px" onclick="addReward()">Add reward</button><div class="catalog">${(state.rewards||[]).map(r=>`<div class="catalog-row"><div class="thumb">${r.icon||'🎁'}</div><div><b>${r.name}</b><div class="small muted">${r.description}</div></div><strong>${r.cost} pts</strong></div>`).join('')||'<div class="notice">No rewards in this catalog yet.</div>'}</div></div>`}
