/* ===== v10.2 reliability patch: role flows, per-child wallets, persistent demo data ===== */
function activeChild(){
  if(!state.children?.length) return null;
  return state.children.find(c=>String(c.id)===String(state.activeChildId)) || state.children[0];
}
function childPoints(childId){
  const id=String(childId||activeChild()?.id||'');
  if(!id) return 0;
  if(state.pointsByChild?.[id]!==undefined) return Number(state.pointsByChild[id])||0;
  return 0;
}
function childLedger(childId){
  const id=String(childId||activeChild()?.id||'');
  if(!id) return [];
  state.ledgerByChild=state.ledgerByChild||{};
  state.ledgerByChild[id]=state.ledgerByChild[id]||[];
  return state.ledgerByChild[id];
}
function setChildPoints(childId,value){
  const id=String(childId||''); if(!id)return;
  state.pointsByChild=state.pointsByChild||{}; state.pointsByChild[id]=Math.max(0,Number(value)||0);
  state.rewardPoints=state.pointsByChild[id]; state.ledger=childLedger(id);
}
function addChildPoints(childId,amount,description,type='earned'){
  const id=String(childId||''); if(!id)return false;
  const n=Number(amount)||0; if(!n)return false;
  setChildPoints(id,childPoints(id)+n);
  childLedger(id).push({date:simulationDate(),description,amount:n,type});
  state.rewardPoints=childPoints(id); state.ledger=childLedger(id); saveLocalOnly(); return true;
}
function selectChild(childId){
  const c=state.children?.find(x=>String(x.id)===String(childId)); if(!c)return;
  state.activeChildId=c.id; state.childName=c.name; state.rewardPoints=childPoints(c.id); state.ledger=childLedger(c.id); saveLocalOnly(); render();
}
async function loadUserData(){
  if(!supabaseClient||!state.authUser)return;
  try{
    const parentLike=isParentLike();
    if(state.authRole==='manager'||state.authRole==='owner'){
      let pq=supabaseClient.from('programs').select('id,name,sport,sessions,price,attendance_payback,schedule,details,spots,venue_id,manager_id,venues(name)').order('created_at');
      if(state.authRole==='manager') pq=pq.eq('manager_id',state.authUser.id);
      const q=await pq;
      if(!q.error){
        state.programs=(q.data||[]).filter(p=>p.name!=='Saturday Soccer — U10').map((p,i)=>{
          const dates=extractDatesFromSchedule(p.schedule);
          return {id:i+1,dbId:p.id,managerId:p.manager_id,name:p.name,sport:p.sport,sessions:p.sessions||8,price:Number(p.price||0),attendancePayback:Number(p.attendance_payback||0),venue:p.venues?.name||'Venue TBD',details:p.details||'',scheduleWeeks:dates,firstDate:dates[0]||null,slots:[{id:'db-'+p.id,label:(String(p.schedule||'').split(' • ')[0]||'Schedule to be announced'),spots:p.spots??0,capacity:p.spots??0}],managerName:'Program manager'};
        });
      }
      if(state.programs.length){
        const mids=[...new Set(state.programs.map(p=>p.managerId).filter(Boolean))];
        if(mids.length){const mq=await supabaseClient.from('profiles').select('id,name').in('id',mids);if(!mq.error){const names=Object.fromEntries((mq.data||[]).map(x=>[x.id,x.name]));state.programs=state.programs.map(p=>({...p,managerName:names[p.managerId]||'Program manager'}));}}
      }
      let rq=supabaseClient.from('rewards').select('id,name,description,cost,icon,image_url,manager_id').eq('active',true).order('created_at');
      if(state.authRole==='manager'||state.authRole==='owner') rq=rq.eq('manager_id',state.authUser.id);
      const rr=await rq;if(!rr.error)state.rewards=(rr.data||[]).map((x,i)=>({id:i+1,dbId:x.id,name:x.name,description:x.description||'',cost:Number(x.cost||0),icon:x.icon||'🎁',image:x.image_url||''}));
      const pids=state.programs.map(p=>p.dbId).filter(Boolean);
      if(pids.length){
        const sq=await supabaseClient.from('sessions').select('id,name,sport,session_date,start_time,end_time,status,description,max_players,program_id,venue_id,venues(name)').in('program_id',pids).order('session_date');
        if(!sq.error)state.managerSessions=(sq.data||[]).map(s=>({id:s.id,dbId:s.id,name:s.name,sport:s.sport,date:s.session_date,start:s.start_time,end:s.end_time,status:s.status,description:s.description,maxPlayers:s.max_players,programId:s.program_id,venue:s.venues?.name||'Venue TBD'}));
        state.sessions=state.managerSessions;
        const pc=await supabaseClient.from('program_children').select('program_id,child_id').in('program_id',pids);
        const childIds=[...new Set((pc.data||[]).map(x=>x.child_id).filter(Boolean))];
        if(childIds.length){const cq=await supabaseClient.from('children').select('id,name,photo_url').in('id',childIds);if(!cq.error)state.managerChildren=cq.data||[];}
      }
      if(isOwner()){
        const people=await supabaseClient.from('profiles').select('id,name,email,role,created_at').order('created_at',{ascending:false});
        if(!people.error)state.people=people.data||[];
      }
    }
    if(parentLike){
      const linksQ=await supabaseClient.from('parent_children').select('child_id').eq('parent_id',state.authUser.id);
      const ids=(linksQ.data||[]).map(x=>x.child_id).filter(Boolean);
      if(ids.length){
        const cq=await supabaseClient.from('children').select('id,name,photo_url').in('id',ids);
        if(!cq.error)state.children=cq.data||[];
        const enroll=await supabaseClient.from('program_children').select('program_id,child_id').in('child_id',ids);
        if(!enroll.error)state.enrolledPrograms=enroll.data||[];
        if(!state.activeChildId||!ids.includes(state.activeChildId))state.activeChildId=ids[0];
        const c=activeChild(); if(c){state.childName=c.name;state.rewardPoints=childPoints(c.id);state.ledger=childLedger(c.id);}
        // Load any existing reward ledger rows when the table exposes them.
        const lq=await supabaseClient.from('reward_ledger').select('*').in('child_id',ids).order('created_at',{ascending:true});
        if(!lq.error){
          for(const row of (lq.data||[])){
            const id=String(row.child_id), amount=Number(row.amount??row.points??0)||0;
            if(!state.ledgerByChild[id] || !state.ledgerByChild[id].some(x=>x.dbId===row.id)){
              state.ledgerByChild[id]=state.ledgerByChild[id]||[];
              state.ledgerByChild[id].push({dbId:row.id,date:row.created_at||simulationDate(),description:row.description||row.reason||'Points',amount,type:row.type|| (amount<0?'spent':'earned')});
            }
            state.pointsByChild[id]=state.ledgerByChild[id].reduce((sum,x)=>sum+Number(x.amount||0),0);
          }
        }
      }
    }
  }catch(err){console.warn('User data load skipped.',err)}
}
function extractDatesFromSchedule(schedule){
  const s=String(schedule||''); return [...s.matchAll(/\b(20\d{2}-\d{2}-\d{2})\b/g)].map(m=>m[1]);
}
function managerRewardChild(){return activeManagerChildId()}
function activeManagerChildId(){
  const id=state.activeManagerChildId||state.managerChildren?.[0]?.id; if(id)state.activeManagerChildId=id; return id||null;
}
async function awardPoints(kind,amount=10,childId=activeManagerChildId()){
  const id=String(childId||''); if(!id)return toast('No child is selected for this points award.');
  const n=Math.max(1,Number(amount)||10);
  addChildPoints(id,n,`${kind} bonus`,'earned');
  if(supabaseClient){
    const q=await supabaseClient.from('reward_ledger').insert({child_id:id,amount:n,description:`${kind} bonus`,type:'earned'});
    if(q.error)console.warn('Reward ledger database write skipped:',q.error.message);
  }
  toast(`+${n} points for ${kind}`);render();
}
